-- Real roles and confirmed identities. Synthetic fixtures only; no outbound calls.
BEGIN;
SET LOCAL statement_timeout='25s';
DO $test$
DECLARE root_id uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); driver_id uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); unconfirmed uuid:=gen_random_uuid();
 firm uuid; existing_firm uuid:=gen_random_uuid(); invitation uuid:=gen_random_uuid(); driver_invitation uuid:=gen_random_uuid(); other_invitation uuid:=gen_random_uuid();
 r jsonb; again jsonb; lease jsonb; payload jsonb; denied boolean; app_id uuid; before_count integer;
 owner_email text:='owner-'||owner_id||'@example.invalid'; driver_email text:='driver-'||driver_id||'@example.invalid'; today date:=(now() AT TIME ZONE 'Europe/Sofia')::date;
BEGIN
 INSERT INTO public.companies(id,name,slug,setup_completed_at) VALUES(existing_firm,'Existing fixture','invitation-'||existing_firm,clock_timestamp());
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(root_id,'root-'||root_id||'@example.invalid',now()),(owner_id,owner_email,now()),(driver_id,driver_email,now()),(outsider,'outsider-'||outsider||'@example.invalid',now()),(unconfirmed,'unconfirmed-'||unconfirmed||'@example.invalid',NULL);
 UPDATE public.profiles SET role='SUPER_ADMIN',company_id=NULL WHERE id=root_id;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',root_id,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 IF public.create_partner_invitation(invitation,'company',upper(owner_email),NULL)<>invitation OR public.create_partner_invitation(invitation,'company',owner_email,NULL)<>invitation THEN RAISE EXCEPTION 'FAIL creation idempotency'; END IF;
 r:=public.resolve_partner_access('company',invitation);
 IF r->>'destination'<>'/admin/companies' OR (SELECT role FROM public.profiles WHERE id=root_id)<>'SUPER_ADMIN' THEN RAISE EXCEPTION 'FAIL super administrator downgrade'; END IF;
 denied:=false; BEGIN PERFORM public.claim_partner_invitation_email(invitation,root_id,false); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL client email service privileges'; END IF;
 RESET ROLE;
 -- Neither a fake JWT email nor an editable profile email grants the invitation.
 UPDATE public.profiles SET email=owner_email WHERE id=outsider;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated','email',owner_email)::text,true); SET LOCAL ROLE authenticated;
 r:=public.resolve_partner_access('company',invitation);
 IF r->>'status'<>'denied' OR EXISTS(SELECT 1 FROM public.partner_invitations) THEN RAISE EXCEPTION 'FAIL false identity or invitation RLS'; END IF;
 denied:=false;BEGIN PERFORM public.create_partner_invitation(gen_random_uuid(),'company',owner_email,NULL);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL customer invitation creation'; END IF;
 IF jsonb_array_length(public.my_partner_invitation_data())<>0 THEN RAISE EXCEPTION 'FAIL foreign invitation export'; END IF;
 denied:=false;BEGIN PERFORM public.submit_driver_application(existing_firm,'Uninvited','+359000000000','1–3',false,'');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL generic company link grants application'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',unconfirmed,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 IF public.resolve_partner_access('driver',NULL)->>'reason'<>'missing_email' THEN RAISE EXCEPTION 'FAIL unconfirmed identity'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',owner_id,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 r:=public.resolve_partner_access('company',invitation); again:=public.resolve_partner_access('company',invitation);
 IF jsonb_array_length(public.my_partner_invitation_data())<>1 THEN RAISE EXCEPTION 'FAIL personal invitation export'; END IF;
 firm:=(r->>'company_id')::uuid;
 IF r IS DISTINCT FROM again OR r->>'destination'<>'/company/setup' OR (SELECT company_id FROM public.profiles WHERE id=owner_id)<>firm OR (SELECT role FROM public.profiles WHERE id=owner_id)<>'COMPANY_ADMIN' THEN RAISE EXCEPTION 'FAIL automatic company binding'; END IF;
 IF EXISTS(SELECT 1 FROM public.companies WHERE id=firm AND (is_active OR setup_completed_at IS NOT NULL)) THEN RAISE EXCEPTION 'FAIL draft visible as active'; END IF;
 denied:=false; BEGIN UPDATE public.companies SET is_active=true WHERE id=firm; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL direct draft activation bypass'; END IF;
 payload:=jsonb_build_object('name','Invited firm','legal_name','Invited company EOOD','registration_id','123456789','phone','+359000000000','address','Test address 1','service_city','Левски','permit_number','TEST','permit_expires_on',today+90,'base_fare',2.15,'min_fare',0,'price_per_km',1.23,'price_per_minute',0.17,'dispatch_radius_km',5);
 denied:=false; BEGIN PERFORM public.complete_company_setup(firm,payload||'{"price_per_km":-1}'); EXCEPTION WHEN OTHERS THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL invalid company prices'; END IF;
 r:=public.complete_company_setup(firm,payload);
 again:=public.complete_company_setup(firm,payload||'{"price_per_km":99}');
 IF r IS DISTINCT FROM again OR (r->>'price_per_km')::numeric<>1.23 OR r->>'setup_completed_at' IS NULL OR NOT (r->>'is_active')::boolean OR r->>'legal_verified_at' IS NOT NULL THEN RAISE EXCEPTION 'FAIL confirmed setup or false legal verification'; END IF;
 IF public.resolve_partner_access('company',NULL)->>'destination'<>'/admin/dashboard' THEN RAISE EXCEPTION 'FAIL subsequent company login'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_invitations WHERE kind='company') THEN RAISE EXCEPTION 'FAIL firm reads platform invitations'; END IF;
 denied:=false;BEGIN PERFORM public.create_partner_invitation(gen_random_uuid(),'driver',driver_email,existing_firm);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL foreign-company invitation'; END IF;
 PERFORM public.create_partner_invitation(driver_invitation,'driver',driver_email,firm);
 RESET ROLE;
 -- Sending is leased; concurrent callers cannot send twice, and lost replies reuse the key.
 SET LOCAL ROLE service_role;
 lease:=public.claim_partner_invitation_email(driver_invitation,owner_id,false);
 IF NOT (lease->>'claimed')::boolean OR (public.claim_partner_invitation_email(driver_invitation,owner_id,false)->>'claimed')::boolean THEN RAISE EXCEPTION 'FAIL email lease exclusivity'; END IF;
 IF NOT public.finish_partner_invitation_email(driver_invitation,(lease->>'lease')::uuid,'synthetic-message',NULL) THEN RAISE EXCEPTION 'FAIL email result persistence'; END IF;
 IF (public.claim_partner_invitation_email(driver_invitation,owner_id,false)->>'claimed')::boolean THEN RAISE EXCEPTION 'FAIL duplicate email send'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',driver_id,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 r:=public.resolve_partner_access('driver',driver_invitation); again:=public.resolve_partner_access('any',NULL);
 IF r->>'status'<>'preparation' OR again->>'destination'<>'/driver/access' OR r->>'company_id'<>firm::text OR (SELECT role FROM public.profiles WHERE id=driver_id)<>'CUSTOMER' OR EXISTS(SELECT 1 FROM public.drivers WHERE user_id=driver_id) THEN RAISE EXCEPTION 'FAIL premature driver privileges'; END IF;
 app_id:=public.begin_driver_onboarding(firm,'Invited driver','+359000000000','1–3',true,'');
 IF (public.resolve_partner_access('driver',NULL)->>'application_id')::uuid<>app_id THEN RAISE EXCEPTION 'FAIL preparation resume'; END IF;
 denied:=false;BEGIN PERFORM public.begin_driver_onboarding(existing_firm,'Invited driver','+359000000000','1–3',false,'');EXCEPTION WHEN OTHERS THEN denied:=true;END;
 IF NOT denied THEN RAISE EXCEPTION 'FAIL candidate switches company'; END IF;
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',root_id,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 PERFORM public.create_partner_invitation(other_invitation,'driver','outsider-'||outsider||'@example.invalid',firm);
 PERFORM public.revoke_partner_invitation(other_invitation);
 RESET ROLE;
 PERFORM set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true); SET LOCAL ROLE authenticated;
 IF public.resolve_partner_access('driver',other_invitation)->>'status'<>'denied' THEN RAISE EXCEPTION 'FAIL revoked invitation'; END IF;
 RESET ROLE;
 UPDATE public.partner_invitations SET status='pending',expires_at=clock_timestamp()-interval '1 minute' WHERE id=other_invitation;
 SET LOCAL ROLE authenticated;
 IF public.resolve_partner_access('driver',other_invitation)->>'status'<>'denied' THEN RAISE EXCEPTION 'FAIL expired invitation'; END IF;
 RESET ROLE;
 PERFORM set_config('leski.partner_invitation_test','passed',true);
END $test$;
SELECT current_setting('leski.partner_invitation_test') AS partner_invitation_test;
ROLLBACK;
